-- Pixel Societies — live room summaries
--
-- One row per group: a short topic + dynamic-of-the-room blurb,
-- regenerated by an LLM on demand. Persistent so anyone joining the
-- room sees what's been happening; pushed via Realtime so when one
-- person hits "Refresh" everyone sees the update.

create table if not exists public.world_group_room_summaries (
  world_group_id   uuid primary key
                   references public.world_groups(id) on delete cascade,
  topic            text,
  dynamic          text,
  generated_at     timestamptz not null default now(),
  source_seq_high  bigint
);

alter table public.world_group_room_summaries enable row level security;

drop policy if exists "wgrsum: members can read"
  on public.world_group_room_summaries;
create policy "wgrsum: members can read"
  on public.world_group_room_summaries for select
  using (public.is_world_group_member(world_group_id, auth.uid()));

-- Writes happen via the backend (service role); no public insert/update
-- policy.

do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    begin
      alter publication supabase_realtime add table public.world_group_room_summaries;
    exception when duplicate_object then null;
    end;
  end if;
end $$;
